"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal, InvalidOperation
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    """Return a field value, treating missing fields as the legacy empty string."""
    if row is None:
        return ""
    return row.get(column, "")


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion: an empty value is numeric zero."""
    if value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Perform a legacy LOOKUP, preserving row order and excluding soft deletes."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if _value(row, "DEL_FLG") == "Y":
            continue
        if _value(row, key_column) == key_value:
            return _value(row, output_column)
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order record using the legacy VRL rule-file order."""
    errors: list[dict] = []
    old_record = {} if event == "INSERT" or old is None else old

    def fail(code: str, message: str) -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": "BLOCK",
            }
        )

    if table == "ORD_HEADER":
        # ORD-001: INSERT, UPDATE
        if event in ("INSERT", "UPDATE"):
            discount = _number(_value(record, "DISC_PCT"))
            if not (discount >= Decimal("0") and discount <= Decimal("100")):
                fail("E5001", "Discount out of range")

        # ORD-002: UPDATE
        if event == "UPDATE":
            discount = _number(_value(record, "DISC_PCT"))
            owner_role = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if (
                discount > Decimal("20")
                and owner_role != "MGR"
                and owner_role != "ADMIN"
            ):
                fail(
                    "E5002",
                    "Discount over 20 percent requires manager role",
                )

        # ORD-003: UPDATE
        if event == "UPDATE":
            old_status = _value(old_record, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                fail("E5003", "Invoiced order can only be cancelled")

    elif table == "ORD_LINE":
        # ORD-004: INSERT, UPDATE
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > Decimal("0")):
                fail("E5004", "Quantity must be positive")

        # ORD-005: INSERT
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                fail("E5005", "Product not active")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
